pub open spec fn opt_add<V>(a: Option<V>, b: Option<V>) -> Option<V> {
    if b is Some {
        b
    } else {
        a
    }
}

#[doc(hidden)]
#[verifier::inline]
pub open spec fn opt_agree<V>(a: Option<V>, b: Option<V>) -> bool {
    a is Some && b is Some ==> a->0 == b->0
}

#[doc(hidden)]
#[verifier::inline]
pub open spec fn opt_sub<V>(a: Option<V>, b: Option<V>) -> Option<V> {
    if b is Some {
        Option::None
    } else {
        a
    }
}

