            //     pre.request_stored(j) ==> pre.slots[j]
            // But pre.slots[j] == false, so !pre.request_stored(j).
            assert(!pre.request_stored(j)) by {
                assert(pre.request_stored_inv());
                if pre.request_stored(j) {
                    assert(pre.slots.index(j));
                }
            };

