            //     pre.combiner_has(j) ==> pre.slots[j]
            // But pre.slots[j] == false, so !pre.combiner_has(j).
            assert(!pre.combiner_has(j)) by {
                assert(pre.combiner_has_inv());
                if pre.combiner_has(j) {
                    assert(pre.slots.index(j));
                }
